code.C:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* defangIPaddr(char* address) {
    size_t n = strlen(address);
    char* result = (char*)malloc(3 * n + 1);
    if (!result) return NULL;
    size_t j = 0;
    for (size_t i = 0; i < n; ++i) {
        if (address[i] == '.') {
            result[j++] = '[';
            result[j++] = '.';
            result[j++] = ']';
        } else {
            result[j++] = address[i];
        }
    }
    result[j] = '\0';
    return result;
}

